import java.util.*;
public class Main {
    static long percentile(long[] sorted,int percent){int rank=(percent*sorted.length+99)/100;return sorted[rank-1];}
    public static void main(String[] args){Scanner s=new Scanner(System.in);long sloMs=s.nextLong();int n=s.nextInt();Map<String,List<String>> paths=new TreeMap<>();Map<String,Long> totals=new TreeMap<>();long[] durations=new long[n];String slowest=null;long slowestMs=-1;for(int i=0;i<n;i++){String traceId=s.next(),service=s.next();long ms=s.nextLong();paths.computeIfAbsent(traceId,k->new ArrayList<>()).add(service);totals.merge(traceId,ms,Long::sum);durations[i]=ms;if(slowest==null||ms>slowestMs||(ms==slowestMs&&service.compareTo(slowest)<0)){slowestMs=ms;slowest=service;}}for(Map.Entry<String,List<String>> e:paths.entrySet())System.out.println(e.getKey()+" "+String.join(" -> ",e.getValue())+" total="+totals.get(e.getKey()));long p95=0;if(n>0){long[] sorted=Arrays.copyOf(durations,n);Arrays.sort(sorted);p95=percentile(sorted,95);}System.out.println("p95="+p95);System.out.println(p95<=sloMs?"SLO_MET":"SLO_VIOLATED");System.out.println("slowest="+(slowest==null?"NONE 0":slowest+" "+slowestMs));}
}
